def transform(grid):
    out = [row[:] for row in grid]
    a = b = None
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 1:
                a = (r, c)
            elif value == 2:
                b = (r, c)
    if a is None or b is None:
        return out
    r, c = a
    tr, tc = b
    dr, dc = tr-r, tc-c
    sr = 1 if dr > 0 else -1 if dr < 0 else 0
    sc = 1 if dc > 0 else -1 if dc < 0 else 0
    nr, nc = abs(dr), abs(dc)
    if nr == 0 or nc == 0:
        # Aligned markers: connect them directly.
        while (r, c) != (tr, tc):
            r += sr
            c += sc
            if (r, c) != (tr, tc):
                out[r][c] = 3
        return out
    # Follow the diagonal toward the target, leave one diagonal step for the end,
    # then traverse the excess distance along the dominant axis.
    diagonal_steps = min(nr, nc) - 1
    for _ in range(diagonal_steps):
        r += sr
        c += sc
        out[r][c] = 3
    if nr > nc:
        for _ in range(nr - diagonal_steps - 1):
            r += sr
            out[r][c] = 3
    elif nc > nr:
        for _ in range(nc - diagonal_steps - 1):
            c += sc
            out[r][c] = 3
    return out
